class Solution {
public:
    long long pickGifts(vector<int>& gifts, int k) {
        priority_queue<int> pq(gifts.begin(), gifts.end());
        for (int i = 0; i < k; i++) {
            int top = pq.top();
            pq.pop();
            int s = (int)sqrt((double)top);
            if ((long long)(s + 1) * (s + 1) <= top) s++;
            pq.push(s);
        }
        long long sum = 0;
        while (!pq.empty()) {
            sum += pq.top();
            pq.pop();
        }
        return sum;
    }
};
